// Heat diffusion on the GPU: each step replaces every cell with
// (4 * self + left + right + up + down) / 8, computed by a WebGPU compute kernel.

const WORKGROUP = 16;

const SHADER = `
struct Params {
  width: u32,
  height: u32,
  pad0: u32,
  pad1: u32,
}

@group(0) @binding(0) var<uniform> params: Params;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(${WORKGROUP}, ${WORKGROUP})
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  let x = id.x;
  let y = id.y;
  if (x >= params.width || y >= params.height) {
    return;
  }

  let w = params.width;
  let xl = select(x - 1u, 0u, x == 0u);
  let xr = min(x + 1u, w - 1u);
  let yu = select(y - 1u, 0u, y == 0u);
  let yd = min(y + 1u, params.height - 1u);

  let c = src[y * w + x];
  let l = src[y * w + xl];
  let r = src[y * w + xr];
  let u = src[yu * w + x];
  let d = src[yd * w + x];

  dst[y * w + x] = (4u * c + l + r + u + d) / 8u;
}
`;

interface Grid {
  width: number;
  height: number;
  steps: number;
  cells: Uint32Array;
}

async function readGrid(path: string): Promise<Grid> {
  const text = await Deno.readTextFile(path);
  const tokens = text.split(/\s+/).filter((t) => t.length > 0);

  let pos = 0;
  const next = (): number => {
    if (pos >= tokens.length) {
      throw new Error("input ended early");
    }
    return Number(tokens[pos++]);
  };

  const width = next();
  const height = next();
  const steps = next();
  const cells = new Uint32Array(width * height);
  for (let i = 0; i < cells.length; i++) {
    cells[i] = next();
  }
  return { width, height, steps, cells };
}

async function diffuse(grid: Grid): Promise<Uint32Array> {
  const { width, height, steps, cells } = grid;
  const byteLength = cells.byteLength;

  const adapter = await navigator.gpu?.requestAdapter();
  if (!adapter) {
    throw new Error("no WebGPU adapter available");
  }
  const device = await adapter.requestDevice();

  const usage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST | GPUBufferUsage.COPY_SRC;
  const bufferA = device.createBuffer({ size: byteLength, usage });
  const bufferB = device.createBuffer({ size: byteLength, usage });
  const staging = device.createBuffer({
    size: byteLength,
    usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
  });
  const params = device.createBuffer({
    size: 16,
    usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
  });

  device.queue.writeBuffer(bufferA, 0, cells);
  device.queue.writeBuffer(params, 0, new Uint32Array([width, height, 0, 0]));

  const module = device.createShaderModule({ code: SHADER });
  const pipeline = device.createComputePipeline({
    layout: "auto",
    compute: { module, entryPoint: "main" },
  });

  const layout = pipeline.getBindGroupLayout(0);
  const makeGroup = (src: GPUBuffer, dst: GPUBuffer) =>
    device.createBindGroup({
      layout,
      entries: [
        { binding: 0, resource: { buffer: params } },
        { binding: 1, resource: { buffer: src } },
        { binding: 2, resource: { buffer: dst } },
      ],
    });
  const groupAB = makeGroup(bufferA, bufferB);
  const groupBA = makeGroup(bufferB, bufferA);

  // Each step is its own compute pass, so the GPU runs them in order and
  // every step reads what the previous one wrote.
  const encoder = device.createCommandEncoder();
  const dispatchX = Math.ceil(width / WORKGROUP);
  const dispatchY = Math.ceil(height / WORKGROUP);
  for (let s = 0; s < steps; s++) {
    const pass = encoder.beginComputePass();
    pass.setPipeline(pipeline);
    pass.setBindGroup(0, s % 2 === 0 ? groupAB : groupBA);
    pass.dispatchWorkgroups(dispatchX, dispatchY);
    pass.end();
  }
  const result = steps % 2 === 0 ? bufferA : bufferB;
  encoder.copyBufferToBuffer(result, 0, staging, 0, byteLength);
  device.queue.submit([encoder.finish()]);

  await staging.mapAsync(GPUMapMode.READ);
  const out = new Uint32Array(staging.getMappedRange().slice(0));
  staging.unmap();

  bufferA.destroy();
  bufferB.destroy();
  staging.destroy();
  params.destroy();
  device.destroy();

  return out;
}

async function writeAll(bytes: Uint8Array): Promise<void> {
  let offset = 0;
  while (offset < bytes.length) {
    offset += await Deno.stdout.write(bytes.subarray(offset));
  }
}

async function main(): Promise<void> {
  const path = Deno.args[0];
  if (path === undefined) {
    throw new Error("usage: deno run ... main.ts <grid-file>");
  }

  const grid = await readGrid(path);
  const out = await diffuse(grid);

  const lines: string[] = [];
  let sum = 0;
  for (let y = 0; y < grid.height; y++) {
    const row = out.subarray(y * grid.width, (y + 1) * grid.width);
    lines.push(Array.from(row).join(" "));
    for (const v of row) {
      sum += v;
    }
  }
  lines.push(`SUM ${sum}`);

  await writeAll(new TextEncoder().encode(lines.join("\n") + "\n"));
}

try {
  await main();
} catch (err) {
  console.error(err instanceof Error ? err.message : err);
  Deno.exit(1);
}

